     1	package br.com.loja.pedidos.entrega;
     3	import java.io.IOException;
     4	import java.math.BigDecimal;
     5	import java.math.RoundingMode;
     6	import java.net.URI;
     7	import java.net.URLEncoder;
     8	import java.net.http.HttpClient;
     9	import java.net.http.HttpRequest;
    10	import java.net.http.HttpResponse;
    11	import java.nio.charset.StandardCharsets;
    12	import java.time.Duration;
    13	import java.util.Optional;
    14	import java.util.concurrent.TimeUnit;
    16	import org.springframework.beans.factory.annotation.Value;
    17	import org.springframework.stereotype.Component;
    19	import tools.jackson.databind.JsonNode;
    20	import tools.jackson.databind.ObjectMapper;
    23	@Component
    24	public class TransLog implements Transportadora {
    26	    private static final Duration TEMPO_LIMITE = Duration.ofSeconds(2);
    28	    private final String url;
    29	    private final ObjectMapper json;
    30	    private final HttpClient http = HttpClient.newBuilder().connectTimeout(TEMPO_LIMITE).build();
    32	    public TransLog(@Value("${translog.url}") String url, ObjectMapper json) {
    33	        this.url = url.endsWith("/") ? url.substring(0, url.length() - 1) : url;
    34	        this.json = json;
    35	    }
    37	    @Override
    38	    public Optional<CotacaoEntrega> cotar(String cep, BigDecimal pesoKg, String servico) {
    39	        String consulta = url + "/cotacao?cep=" + codificar(cep) + "&pesoKg=" + codificar(formatarPeso(pesoKg))
    40	                + "&servico=" + codificar(servico);
    41	        HttpResponse<String> resposta;
    42	        try {
    43	            HttpRequest requisicao = HttpRequest.newBuilder(URI.create(consulta)).timeout(TEMPO_LIMITE).GET().build();
    44	            resposta = http.sendAsync(requisicao, HttpResponse.BodyHandlers.ofString())
    45	                    .get(TEMPO_LIMITE.toMillis(), TimeUnit.MILLISECONDS);
    46	        } catch (InterruptedException e) {
    47	            Thread.currentThread().interrupt();
    48	            throw new TransportadoraIndisponivelException("Consulta à TransLog interrompida", e);
    49	        } catch (Exception e) {
    50	            throw new TransportadoraIndisponivelException("TransLog não respondeu", e);
    51	        }
    52	        if (resposta.statusCode() == 404) {
    53	            return Optional.empty();
    54	        }
    55	        if (resposta.statusCode() != 200) {
    56	            throw new TransportadoraIndisponivelException("TransLog respondeu " + resposta.statusCode(), null);
    57	        }
    58	        try {
    59	            JsonNode corpo = json.readTree(resposta.body());
    60	            JsonNode valor = corpo.get("valor");
    61	            JsonNode prazo = corpo.get("prazoDias");
    62	            if (valor == null || !valor.isNumber() || prazo == null || !prazo.isIntegralNumber()
    63	                    || !prazo.canConvertToInt() || valor.decimalValue().signum() < 0 || prazo.intValue() < 0) {
    64	                throw new IOException("Resposta inesperada da TransLog: " + resposta.body());
    65	            }
    66	            return Optional.of(new CotacaoEntrega(valor.decimalValue(), prazo.intValue()));
    67	        } catch (Exception e) {
    68	            throw new TransportadoraIndisponivelException("Resposta inválida da TransLog", e);
    69	        }
    70	    }
    72	    private static String formatarPeso(BigDecimal pesoKg) {
    73	        BigDecimal peso = pesoKg.stripTrailingZeros();
    74	        return (peso.scale() < 2 ? peso.setScale(2, RoundingMode.UNNECESSARY) : peso).toPlainString();
    75	    }
    77	    private static String codificar(String valor) {
    78	        return URLEncoder.encode(valor, StandardCharsets.UTF_8);
    79	    }
    80	}
