    11	@Component
    12	public class Cartao implements FormaPagamento {
    14	    private static final int MAXIMO_PARCELAS = 12;
    15	    private static final int MAXIMO_SEM_JUROS = 3;
    16	    private static final BigDecimal JUROS_MENSAL = new BigDecimal("0.0199");
    18	    @Override
    19	    public String codigo() {
    20	        return "CARTAO";
    21	    }
    23	    @Override
    24	    public boolean aceitaParcelas(int parcelas) {
    25	        return parcelas >= 1 && parcelas <= MAXIMO_PARCELAS;
    26	    }
    28	    @Override
    29	    public ResultadoPagamento calcular(BigDecimal totalPedido, int parcelas, boolean usouCupom) {
    30	        if (parcelas <= MAXIMO_SEM_JUROS) {
    31	            BigDecimal parcela = Dinheiro.centavos(totalPedido.divide(BigDecimal.valueOf(parcelas), MathContext.DECIMAL128));
    32	            return new ResultadoPagamento(totalPedido, parcelas, parcela);
    33	        }
    35	        BigDecimal descontoFator = BigDecimal.ONE.divide(BigDecimal.ONE.add(JUROS_MENSAL).pow(parcelas), MathContext.DECIMAL128);
    36	        BigDecimal parcela = Dinheiro.centavos(totalPedido.multiply(JUROS_MENSAL)
    37	                .divide(BigDecimal.ONE.subtract(descontoFator), MathContext.DECIMAL128));
    38	        return new ResultadoPagamento(parcela.multiply(BigDecimal.valueOf(parcelas)), parcelas, parcela);
    39	    }
    40	}
