    69	        BigDecimal subtotal = Dinheiro.centavos(itens.stream().map(ItemCarrinho::valor).reduce(BigDecimal.ZERO, BigDecimal::add));
    70	        BigDecimal peso = itens.stream().map(ItemCarrinho::peso).reduce(BigDecimal.ZERO, BigDecimal::add);
    72	        NivelClube nivel = niveis.buscar(texto(dados, "nivelClube"))
    73	                .orElseThrow(() -> ErroNegocio.invalido("NIVEL_CLUBE_INVALIDO"));
    74	        Regiao regiao = Optional.ofNullable(texto(dados, "regiao")).flatMap(Regiao::deCodigo)
    75	                .orElseThrow(() -> ErroNegocio.invalido("REGIAO_INVALIDA"));
