    83	        BigDecimal frete = nivel.isentaFrete(modalidade) ? Dinheiro.ZERO : Dinheiro.centavos(cotacao.frete());
    85	        Optional<Cupom> cupom = lerCupom(dados);
    86	        BigDecimal descontoCupom = cupom
    87	                .map(c -> Dinheiro.centavos(c.desconto(new ContextoCupom(cpf, itens, subtotal, modalidade, frete))))
    88	                .orElse(Dinheiro.ZERO);
    90	        FormaPagamento forma = formas.buscar(texto(dados, "formaPagamento"))
    91	                .orElseThrow(() -> ErroNegocio.invalido("FORMA_PAGAMENTO_INVALIDA"));
