   115	    private static List<ItemSolicitado> lerItens(JsonNode itens) {
   116	        if (itens == null || !itens.isArray() || itens.isEmpty()) {
   117	            throw ErroNegocio.invalido("PEDIDO_INVALIDO");
   118	        }
   119	        List<ItemSolicitado> lidos = new ArrayList<>();
   120	        Set<String> skus = new HashSet<>();
   121	        for (JsonNode item : itens.values()) {
   122	            String sku = item.isObject() ? texto(item, "sku") : null;
   123	            JsonNode quantidade = item.isObject() ? item.get("quantidade") : null;
   124	            if (sku == null || sku.isBlank() || !skus.add(sku) || quantidade == null || !quantidade.isIntegralNumber()
   125	                    || !quantidade.canConvertToInt() || quantidade.intValue() <= 0) {
   126	                throw ErroNegocio.invalido("PEDIDO_INVALIDO");
   127	            }
   128	            lidos.add(new ItemSolicitado(sku, quantidade.intValue()));
   129	        }
   130	        return lidos;
   131	    }
   133	    private List<ItemCarrinho> conferirCatalogo(List<ItemSolicitado> solicitados) {
   134	        List<ItemCarrinho> itens = new ArrayList<>();
   135	        for (ItemSolicitado solicitado : solicitados) {
   136	            Produto produto = produtos.buscar(solicitado.sku())
   137	                    .orElseThrow(() -> ErroNegocio.invalido("PRODUTO_INEXISTENTE"));
   138	            itens.add(new ItemCarrinho(produto, solicitado.quantidade()));
   139	        }
   140	        if (itens.stream().anyMatch(item -> item.produto().foraDeLinha())) {
   141	            throw ErroNegocio.invalido("PRODUTO_FORA_DE_LINHA");
   142	        }
   143	        if (itens.stream().anyMatch(item -> item.produto().estoque() < item.quantidade())) {
   144	            throw ErroNegocio.invalido("ESTOQUE_INSUFICIENTE");
   145	        }
   146	        return itens;
   147	    }
   149	    private Optional<Cupom> lerCupom(JsonNode dados) {
   150	        JsonNode codigo = dados.get("cupom");
   151	        if (codigo == null || codigo.isNull() || (codigo.isString() && codigo.stringValue().isEmpty())) {
   152	            return Optional.empty();
   153	        }
   154	        if (!codigo.isString()) {
   155	            throw ErroNegocio.invalido("CUPOM_INVALIDO");
   156	        }
   157	        return Optional.of(cupons.buscar(codigo.stringValue()).orElseThrow(() -> ErroNegocio.invalido("CUPOM_INVALIDO")));
   158	    }
   160	    private static int lerParcelas(JsonNode parcelas) {
   161	        if (parcelas == null || parcelas.isNull()) {
   162	            return 1;
   163	        }
   164	        if (!parcelas.isIntegralNumber() || !parcelas.canConvertToInt()) {
   165	            throw ErroNegocio.invalido("PARCELAMENTO_INVALIDO");
   166	        }
   167	        return parcelas.intValue();
   168	    }
   170	    private static String texto(JsonNode no, String campo) {
   171	        JsonNode valor = no.get(campo);
   172	        return valor != null && valor.isString() ? valor.stringValue() : null;
   173	    }
   174	}
